/* ---------- SVG landmarks & shops (isometric, generated by JS) ---------- */
var NS='http://www.w3.org/2000/svg';
var svgLayer=document.createElement('div'); svgLayer.id='svgLayer';
var svg=document.createElementNS(NS,'svg');
svg.setAttribute('xmlns',NS);
svg.style.cssText='width:100%;height:100%;position:absolute;left:0;top:0;overflow:visible';
svgLayer.appendChild(svg); $('shopLayer').appendChild(svgLayer);
function el(tag,attrs,parent){var e=document.createElementNS(NS,tag);for(var k in attrs)e.setAttribute(k,attrs[k]);if(parent)parent.appendChild(e);return e;}
function P(p){return p[0].toFixed(1)+','+p[1].toFixed(1);}
/* iso box: footprint half-steps hx along e1=(2,1), hy along e2=(-2,1), height hz; base centre (cx,cy) */
function isoBox(g,cx,cy,hx,hy,hz,ct,cl,cr){
  var p=function(hxi,hyj,hzz){return [cx+2*hx*hxi-2*hy*hyj, cy+hx*hxi+hy*hyj-hz*hzz];};
  var A=p(-1,-1,1),B=p(1,-1,1),C=p(1,1,1),D=p(-1,1,1);
  var B0=p(1,-1,0),C0=p(1,1,0),D0=p(-1,1,0);
  el('polygon',{points:P(A)+' '+P(B)+' '+P(C)+' '+P(D),fill:ct},g);
  el('polygon',{points:P(B)+' '+P(C)+' '+P(C0)+' '+P(B0),fill:cr},g);
  el('polygon',{points:P(D)+' '+P(C)+' '+P(C0)+' '+P(D0),fill:cl},g);
  return {p:p};
}
function pyramid(g,pfOrBase,top,colorA,colorB){
  var base=(typeof pfOrBase==='function')?{p:pfOrBase}:pfOrBase;   // accept isoBox result OR its p fn
  var b=[base.p(-1,-1,1),base.p(1,-1,1),base.p(1,1,1),base.p(-1,1,1)];
  var tip=[(b[0][0]+b[2][0])/2,b[0][1]-top];
  el('polygon',{points:P(b[0])+' '+P(b[1])+' '+P(tip),fill:colorA},g);
  el('polygon',{points:P(b[1])+' '+P(b[2])+' '+P(tip),fill:colorB},g);
  el('polygon',{points:P(b[2])+' '+P(b[3])+' '+P(tip),fill:colorA},g);
  el('polygon',{points:P(b[3])+' '+P(b[0])+' '+P(tip),fill:colorB},g);
}
function buildPalace(){
  var g=el('g',{},svg), cx=LCX, cy=LCY;
  var hall=isoBox(g,cx,cy-8,26,10,16,'#efe3c8','#d9c9a4','#e6d8b8');
  var hp=hall.p;
  var r1=hp(-1,-1,1),r2=hp(1,-1,1),r3=hp(1,1,1),r4=hp(-1,1,1);
  var m1=[(r1[0]+r4[0])/2,r1[1]-9],m2=[(r2[0]+r3[0])/2,r2[1]-9];
  el('polygon',{points:P(r1)+' '+P(r2)+' '+P(m2)+' '+P(m1),fill:'#c9b78f'},g);
  el('polygon',{points:P(r4)+' '+P(r3)+' '+P(m2)+' '+P(m1),fill:'#dccca6'},g);
  for(var i=-0.7;i<=0.71;i+=0.35){
    var w1=hp(i,1,0.25),w2=hp(i,1,0.8);
    el('line',{x1:w1[0],y1:w1[1],x2:w2[0],y2:w2[1],stroke:'#8d7a52','stroke-width':2},g);
  }
  var bt=isoBox(g,cx-2*20-2*8+2,cy+20-8+8-16,5,5,44,'#efe3c8','#cdbb92','#e2d2ae');
  pyramid({p:bt.p},16,'#caa741','#e3c04f');
  var cf=bt.p(1,1,0.82);
  el('circle',{cx:cf[0],cy:cf[1],r:3.4,fill:'#fff',stroke:'#8d7a52','stroke-width':1},g);
  var vt=isoBox(g,cx+2*24+2*6-2,cy+24-6-10,6,6,26,'#efe3c8','#cdbb92','#e2d2ae');
  pyramid(vt,9,'#b98a4a','#d3a45c');
  return g;
}
function buildBridge(){
  var g=el('g',{},svg);
  /* river axis dir (2,-1)/sqrt5 ; cross dir (-1,-2)... use map-space vectors */
  var ax=2/SQ5, ay=-1/SQ5;          // along river (up-right on screen? y down: (2,-1) means right+up)
  var bx=-1/SQ5*2*0+(-(-1)), by=0;  // placeholder
  // crossing direction = perpendicular in the t/s basis: s increases toward (-1?, ) -> derive:
  // t=(2u+v)/SQ5, s=(-u+2v)/SQ5 => du/ds=-1/SQ5? invert: u=(2t-s)/SQ5, v=(t+2s)/SQ5
  // so d/dt=(2,1)/SQ5 (screen up-down positive y!) and d/ds=(-1,2)/SQ5
  var DX=2/SQ5, DY=1/SQ5;           // along river axis in map px (y down)
  var CX2=-1/SQ5, CY2=2/SQ5;        // across river
  var hw=rHW(RTB)+6;                // half span across
  function D(al,c,h){return [TBX+DX*al+CX2*c*2*0+CX2*c, TBY+DY*al+CY2*c-h];}
  // NOTE: c is measured in map px along (CX2,CY2) unit vector; multiply directly
  function DC(al,c,h){return [TBX+DX*al+CX2*c, TBY+DY*al+CY2*c-h];}
  var AL=12;
  var q1=DC(-AL,-hw,7),q2=DC(AL,-hw,7),q3=DC(AL,hw,7),q4=DC(-AL,hw,7);
  el('polygon',{points:P(q1)+' '+P(q2)+' '+P(q3)+' '+P(q4),fill:'#d9cba8'},g);
  el('polygon',{points:P(q1)+' '+P(q4)+' '+P([q4[0],q4[1]+3])+' '+P([q1[0],q1[1]+3]),fill:'#a89878'},g);
  el('polygon',{points:P(q2)+' '+P(q3)+' '+P([q3[0],q3[1]+3])+' '+P([q2[0],q2[1]+3]),fill:'#b8a884'},g);
  [-hw-6,hw+6].forEach(function(c){
    var fpt=DC(0,c,0);
    el('ellipse',{cx:fpt[0],cy:fpt[1]+2,rx:7,ry:3,fill:'rgba(255,255,255,.75)'},g);
    isoBox(g,fpt[0],fpt[1]-1,2.5,2.5,7,'#d9cba8','#a89878','#c4b490');
  });
  var towers=[];
  [-AL+3,AL-3].forEach(function(al){[-hw*0.55,hw*0.55].forEach(function(c){
    var tp=DC(al,c,7);
    var t=isoBox(g,tp[0],tp[1],3,3,12,'#e6d8b8','#c4b490','#d5c69e');
    pyramid(t,6,'#caa741','#e3c04f');
    towers.push({p:t.p,base:tp});
  });});
  // high walkways between tower tops + suspension chains
  function topPt(al,c){var tp=DC(al,c,7);return [tp[0],tp[1]-12-6];}
  var a1=topPt(-AL+3,-hw*0.55),a2=topPt(-AL+3,hw*0.55),a3=topPt(AL-3,hw*0.55),a4=topPt(AL-3,-hw*0.55);
  el('line',{x1:a1[0],y1:a1[1],x2:a2[0],y2:a2[1],stroke:'#3b6fd4','stroke-width':2.5},g);
  el('line',{x1:a4[0],y1:a4[1],x2:a3[0],y2:a3[1],stroke:'#3b6fd4','stroke-width':2.5},g);
  el('line',{x1:a1[0],y1:a1[1],x2:a4[0],y2:a4[1],stroke:'#3b6fd4','stroke-width':3},g);
  el('line',{x1:a2[0],y1:a2[1],x2:a3[0],y2:a3[1],stroke:'#3b6fd4','stroke-width':3},g);
  [-1,1].forEach(function(sg){
    var top1=topPt(-AL+3,sg*hw*0.55), top2=topPt(AL-3,sg*hw*0.55);
    var e1=DC(-AL-8,sg*(hw+4),6), e2=DC(AL+8,sg*(hw+4),6);
    var mid1=[(top1[0]+e1[0])/2,(top1[1]+e1[1])/2+ -4];
    el('path',{d:'M'+P(e1)+' Q'+P(mid1)+' '+P(top1)+' L'+P(top2)+' Q'+P([(top2[0]+e2[0])/2,(top2[1]+e2[1])/2-4])+' '+P(e2),fill:'none',stroke:'#3b6fd4','stroke-width':1.4},g);
  });
  return g;
}
/* ---------- shops ---------- */
var shopDefs=[];
function findShopSlots(count){
  var slots=[];
  for(var i=-4;i<=4;i++)for(var j=-4;j<=4;j++){
    var mx=LCX+20*i-20*j, my=LCY+10*i+10*j;
    if(Math.abs(mx-LCX)<70&&Math.abs(my-LCY)<34)continue;      // palace
    if(Math.hypot(mx-TBX,my-TBY)<52)continue;                  // bridge
    if(!isBuildable(mx,my))continue;
    slots.push({mx:mx,my:my,d:Math.hypot(mx-LCX,(my-LCY)*2)});
  }
  slots.sort(function(a,b){return a.d-b.d;});
  return slots.slice(0,count);
}
function shopSVG(kind,mx,my){
  var g=el('g',{'class':'popIn'},svg);
  var wallL=kind==='kebab'?'#f2ead8':'#e8f0f8',wallR=kind==='kebab'?'#ddd2ba':'#cfdcef';
  var roof=kind==='kebab'?'#d1362f':'#2f6bd1', roofHi=kind==='kebab'?'#e8564c':'#4f89ea';
  var b=isoBox(g,mx,my-10,7,7,9,wallR,wallL,'#ffffff');
  var p=b.p;
  var r1=p(-1,-1,1),r2=p(1,-1,1),r3=p(1,1,1),r4=p(-1,1,1);
  var o1=[r1[0]-3,r1[1]-1.6],o2=[r2[0]+3,r2[1]-1.6],o3=[r3[0]+3,r3[1]+1.6],o4=[r4[0]-3,r4[1]+1.6];
  el('polygon',{points:P(o1)+' '+P(o2)+' '+P(o3)+' '+P(o4),fill:roof},g);
  el('polygon',{points:P(o1)+' '+P(o2)+' '+P([o2[0],o2[1]+2])+' '+P([o1[0],o1[1]+2]),fill:roofHi},g);
  var s1=p(-0.85,1,0.62),s2=p(0.85,1,0.62);
  var s3=[s2[0]-3,s2[1]+3.5],s4=[s1[0]-3,s1[1]+3.5];
  el('polygon',{points:P(s1)+' '+P(s2)+' '+P(s3)+' '+P(s4),fill:'#fff'},g);
  for(var k=-0.7;k<=0.69;k+=0.35){
    var t1=p(k,1,0.62),t2=[t1[0]-3,t1[1]+3.5];
    var t3=p(k+0.175,1,0.62),t4=[t3[0]-3,t3[1]+3.5];
    el('polygon',{points:P(t1)+' '+P(t3)+' '+P(t4)+' '+P(t2),fill:roofHi},g);
  }
  var d1=p(0.45,1,0),d2=p(0.45,1,0.55),d3=p(0.8,1,0.55),d4=p(0.8,1,0);
  el('polygon',{points:P(d1)+' '+P(d2)+' '+P(d3)+' '+P(d4),fill:'#6b4a2a'},g);
  var w1=p(0.2,-1,0.3),w2=p(0.6,-1,0.3),w3=p(0.6,-1,0.7),w4=p(0.2,-1,0.7);
  el('polygon',{points:P(w1)+' '+P(w2)+' '+P(w3)+' '+P(w4),fill:'#9fd4ff'},g);
  var g1=p(-0.8,1,0.85),g2=p(0.05,1,0.85);
  el('line',{x1:g1[0],y1:g1[1],x2:g2[0],y2:g2[1],stroke:'#fff','stroke-width':3.4},g);
  var tx=el('text',{x:(g1[0]+g2[0])/2,y:(g1[1]+g2[1])/2+1.2,'font-size':3.4,'text-anchor':'middle',fill:'#333','font-family':'Arial','font-weight':'bold'},g);
  tx.textContent=kind==='kebab'?'KEBAB':'BARBER';
  if(kind==='kebab'){
    var dn=p(-0.4,-0.4,1);
    el('rect',{x:dn[0]-2,y:dn[1]-14,width:4,height:12,rx:1.5,fill:'#e8d8b0',stroke:'#b98a4a','stroke-width':0.8},g);
    el('rect',{x:dn[0]-2,y:dn[1]-14,width:4,height:3,rx:1,fill:'#c9b088'},g);
    el('rect',{x:dn[0]-3,y:dn[1]-16,width:6,height:2,rx:1,fill:'#8d7a52'},g);
    el('rect',{x:dn[0]-1.2,y:dn[1]-2,width:2.4,height:2,fill:'#333'},g);
  }else{
    var pp=p(-0.4,-0.4,1);
    el('rect',{x:pp[0]-1.4,y:pp[1]-13,width:2.8,height:13,rx:1.4,fill:'#fff',stroke:'#99aabc','stroke-width':0.5},g);
    for(var s=0;s<4;s++)el('rect',{x:pp[0]-1.4,y:pp[1]-13+s*3.25,width:2.8,height:1.6,fill:s%2?'#2f6bd1':'#ee3333'},g);
    el('circle',{cx:pp[0],cy:pp[1]-14.5,r:1.6,fill:'#e8d8b0'},g);
  }
  return g;
}
function addShop(){
  if(G.shopCount>=14)return;
  var slots=findShopSlots(14);
  if(!slots[G.shopCount])return;
  var sl=slots[G.shopCount];
  var kind=(G.shopCount%2===0)?'kebab':'barber';
  var g=shopSVG(kind,sl.mx,sl.my);
  shopDefs.push({kind:kind,mx:sl.mx,my:sl.my,el:g});
  G.shopCount++;
}
function rebuildShops(){
  shopDefs.forEach(function(s){s.el.remove();});
  shopDefs=[];
  var want=G.shopCount; G.shopCount=0;
  for(var i=0;i<want;i++)addShop();
}
var popStyle=document.createElement('style');
popStyle.textContent='svg g.popIn{transform-box:fill-box;transform-origin:50% 90%;animation:shopPop .45s ease-out}svg g.bump{transform-box:fill-box;transform-origin:50% 90%;animation:shopBump .25s ease-out}@keyframes shopPop{0%{transform:scale(0)}70%{transform:scale(1.2)}100%{transform:scale(1)}}@keyframes shopBump{0%{transform:scale(1)}40%{transform:scale(1.15)}100%{transform:scale(1)}}';
document.head.appendChild(popStyle);

/* ---------- boat routes (straight lines along iso axes) ---------- */
var DIRS=[[2,-1],[-2,1],[-2,-1],[2,1]].map(function(d){var l=Math.hypot(d[0],d[1]);return [d[0]/l,d[1]/l];});
function findRoute(){
  for(var tries=0;tries<24;tries++){
    var d=DIRS[Math.floor(Math.random()*4)];
    var per=[-d[1],d[0]];
    var off=Math.random()*150-75;
    var aimx=LCX+d[0]*30+per[0]*off, aimy=LCY+d[1]*30+per[1]*off;
    // march from far out at sea toward aim until hitting island edge
    var x=aimx+d[0]*430, y=aimy+d[1]*430, found=null;
    for(var st=0;st<430;st+=2){
      x-=d[0]*2; y-=d[1]*2;
      if(x<-20||x>MW+20||y<-20||y>MH+20)break;
      if(maskAt(x,y)){found={x:x,y:y};break;}
    }
    if(!found)continue;
    if(Math.hypot(found.x-LCX,found.y-LCY)>300)continue;
    // approach line outward must be free of land for >=170px
    var clear=0;
    for(var st2=2;st2<=330;st2+=2){
      var qx=found.x+d[0]*st2, qy=found.y+d[1]*st2;
      if(qx<-30||qx>MW+30||qy<-30||qy>MH+30){clear=st2;break;}
      if(maskAt(qx,qy)){clear=st2-2;break;}
      clear=st2;
    }
    if(clear<170)continue;
    var dist=Math.min(160+Math.random()*140,clear);
    return {d:d,from:[found.x+d[0]*dist,found.y+d[1]*dist],to:found};
  }
  return null;
}

/* ---------- entities ---------- */
function sendBoat(){
  if(G.complete)return;
  var room=Math.floor(H_total()-G.adepts-G.transit);
  if(room<1){toast("Housing is full - build more housing!");return;}
  if(G.boats.length>=30)return;
  var r=findRoute();
  if(!r){toast("No clear route to the beach right now");return;}
  var load=Math.min(4,room);
  G.boats.push({d:r.d,fx:r.from[0],fy:r.from[1],tx:r.to[0],ty:r.to[1],
    prog:0,len:Math.hypot(r.to[0]-r.from[0],r.to[1]-r.from[1]),
    state:'sail',load:load,dropped:0,timer:0,alpha:1,bob:Math.random()*6.28,xcur:r.from[0],ycur:r.from[1]});
  G.transit+=load;
}
function spawnRunner(mx,my){
  if(!shopDefs.length)return;
  var sh=shopDefs[Math.floor(Math.random()*shopDefs.length)];
  G.runners.push({x:mx,y:my,tx:sh.mx+(Math.random()*8-4),ty:sh.my+7+(Math.random()*4-2),sp:55+Math.random()*30,hop:Math.random()*6.28,shop:sh});
}
function bumpShop(sh){sh.el.classList.remove('bump');void sh.el.getBoundingClientRect();sh.el.classList.add('bump');}
function updateEntities(dt){
  var i,b;
  for(i=G.boats.length-1;i>=0;i--){
    b=G.boats[i]; b.bob+=dt*6;
    if(b.state==='sail'){
      b.prog+=120*dt;
      if(b.prog>=b.len){b.prog=b.len;b.state='beach';b.timer=0;}
      b.xcur=b.fx+b.d[0]*b.prog; b.ycur=b.fy+b.d[1]*b.prog;
    }else if(b.state==='beach'){
      b.timer-=dt;
      if(b.timer<=0&&b.dropped<b.load){
        b.timer=0.18;b.dropped++;G.transit--;
        spawnRunner(b.tx-b.d[0]*12,b.ty-b.d[1]*12);
      }
      if(b.dropped>=b.load&&b.timer<=0)b.state='leave';
      b.xcur=b.fx+b.d[0]*b.prog; b.ycur=b.fy+b.d[1]*b.prog;
    }else{
      b.prog+=90*dt; b.alpha-=dt/0.9;
      b.xcur=b.tx+b.d[0]*(b.prog-b.len); b.ycur=b.ty+b.d[1]*(b.prog-b.len);
      if(b.alpha<=0)G.boats.splice(i,1);
    }
  }
  for(i=G.runners.length-1;i>=0;i--){
    var ru=G.runners[i];
    var dx=ru.tx-ru.x,dy=ru.ty-ru.y,dl=Math.hypot(dx,dy);
    if(dl<3){G.runners.splice(i,1);G.adepts+=1;bumpShop(ru.shop);continue;}
    var mv=Math.min(ru.sp*dt,dl);
    ru.x+=dx/dl*mv; ru.y+=dy/dl*mv; ru.hop+=dt*12;
  }
}
